const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function menuHTML(items,mobile=false,lang='en'){const path=p=>lang==='en'?p:p.replace(/^\/satin(?=\/|$)/,'/satin/'+lang);return items.filter(m=>m.active!==false).map(m=>m.groups?.length?(mobile?`<details><summary class="${m.key==='wraps'?'wraps-nav':''}">${esc(m.label)}</summary>${m.groups.map(g=>`<div><b>${esc(g.label)}</b>${g.links.filter(l=>l.active!==false).map(l=>`<a href="${esc(path(l.href))}"${/^all\b/i.test(l.label)?' class="all-link"':''}>${esc(l.label)}</a>`).join('')}</div>`).join('')}</details>`:`<button type="button" data-mega="${esc(m.key)}" aria-expanded="false">${esc(m.label)}<svg class="chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M6 9l6 6 6-6"/></svg></button>`):`<a class="${mobile?'plain-link':'studio-nav'}" href="${esc(path(m.href))}">${esc(m.label)}</a>`).join('');}

export function migrateNavigation(items){const rows=structuredClone(items);for(const m of rows){if(m.key==='apparel')for(const g of m.groups||[]){g.links=g.links.filter(l=>l.label!=='DTF print');for(const l of g.links)if(l.label==='DTF transfer')l.href='/satin/shop/dtf-transfers';}if(m.key==='print'){const g=m.groups.find(g=>g.label==='Large Format');if(g&&!g.links.some(l=>l.href.includes('poly-bag')))g.links.push({label:'Poly Bag Lawn Sign',href:'/satin/print-shop/large-format/poly-bag-lawn-sign',active:true});if(!m.groups.some(g=>g.links.some(l=>l.href.startsWith('/satin/print-shop/labels')))){const at=m.groups.findIndex(g=>g.label==='Help');m.groups.splice(at<0?m.groups.length:at,0,{label:'Labels & Stickers',links:[['Labels & stickers','/satin/print-shop/labels'],['Roll labels','/satin/print-shop/labels/roll-labels'],['Sticker sheets','/satin/print-shop/labels/sticker-sheets'],['Die-cut stickers','/satin/print-shop/labels/die-cut-stickers']].map(([label,href])=>({label,href,active:true}))});}}if(m.key==='shop'){const g=m.groups.find(g=>g.label==='Services');if(g)for(const [label,href] of [['Social Media','/satin/social-media-services'],['Videography','/satin/videography']])if(!g.links.some(l=>l.href===href))g.links.push({label,href,active:true});}}if(!rows.some(m=>m.key==='login'))rows.push({key:'login',label:'Log in',href:'/satin/login',active:true,groups:[]});return rows;}

/* Customer accounts: while signed in (non-secret "satin_acct" hint cookie, confirmed once per page by /api/customer/me), every "Log in" link becomes "My account". */
let accountCheck=null;
export function syncAccountLinks(root=document){const hint=/(?:^|;\s*)satin_acct=1/.test(document.cookie),lang=(location.pathname.match(/^\/satin\/(fa|fr|es)(?=\/|$)/)||[])[1],pre='/satin'+(lang?'/'+lang:''),label={fa:'حساب من',fr:'Mon compte',es:'Mi cuenta'}[lang]||'My account';const apply=on=>root.querySelectorAll('a[href]').forEach(a=>{if(a.closest('.nav'))return;const p=a.getAttribute('href').replace(/[?#].*$/,'');if(on&&/^\/satin(?:\/(?:fa|fr|es))?\/login\/?$/.test(p)){a.dataset.loginLabel=a.textContent;a.textContent=label;a.setAttribute('href',pre+'/account/');a.dataset.accountLink='';}else if(!on&&a.hasAttribute('data-account-link')){a.textContent=a.dataset.loginLabel||'Log in';a.setAttribute('href',pre+'/login/');a.removeAttribute('data-account-link');}});if(!hint)return;apply(true);accountCheck??=fetch('/api/customer/me',{credentials:'same-origin'}).then(r=>r.ok?r.json():null).then(d=>!!d?.customer).catch(()=>true);accountCheck.then(ok=>{if(!ok)apply(false);});}
